sys_script_vtable.script:
(function executeQuery(v_table, v_query) {

    var incidentSysId = '28ed75c09747aa10a78db62de053af48';
    var midServerName = 'Crank Mid Server';
    var instanceUrl = 'https://dev340437.service-now.com/api/x_938076_now_utils/incident_data/getIncidents';

    var rm = new sn_ws.RESTMessageV2();
    rm.setEndpoint(instanceUrl);
    rm.setHttpMethod('GET');
    //rm.setMIDServer(midServerName);

    // FIX: Use setRequestHeader instead of setStringParameter
    var token = 'Oqybhj9GOCs9y5Gyemdc35J0Z-LzNApjZ1bfsJPAhC3LPcA8mtNetdvmp8GDtaqQ7KITmnZpHoXVhOiBqod_JQ';
    rm.setRequestHeader('Authorization', 'Bearer ' + token);
    rm.setRequestHeader('priority', 1);
    rm.setRequestHeader('tableName', 'incident');
    rm.setRequestHeader('Accept', 'application/json');

    var response = rm.executeAsync();
    response.waitForResponse(60);

    var httpStatus = response.getStatusCode();
    var responseBody = response.getBody();

    if (httpStatus == 200) {
        var incidentData = JSON.parse(responseBody);
        var resultData = incidentData.result;
        var resultLength = Object.keys(resultData).length; //totoal length of the array elements 

        //gs.info(Object.keys(resultData)[0])


        for (var i = 0; i < resultLength; i++) {

            //gs.info('Incident Numbers ' + resultData[Object.keys(resultData)[i]].number);

            var row = {};
            row.number = resultData[Object.keys(resultData)[i]].number;
            row.short_description = resultData[Object.keys(resultData)[i]].short_description;
            row.category = resultData[Object.keys(resultData)[i]].category;

            v_table.addRow(row);

        }

    } else {
        gs.error('REST Call failed via MID Server with status: ' + httpStatus + '. Error: ' + response.getErrorMessage());
    }

})(v_table, v_query);

